"""Extensiones históricas aditivas, conservadas para migrar v0.1–v0.3."""
CODING_1 = "\n        CREATE TABLE IF NOT EXISTS atajos(catalogo_id INTEGER PRIMARY KEY REFERENCES catalogos(id),secuencia TEXT NOT NULL UNIQUE,favorito INTEGER UNIQUE CHECK(favorito BETWEEN 1 AND 9));\n        CREATE TABLE IF NOT EXISTS archivos_tiff(id INTEGER PRIMARY KEY,trabajo_id INTEGER NOT NULL REFERENCES trabajos(id),ruta TEXT NOT NULL UNIQUE,original TEXT NOT NULL,hash_original TEXT NOT NULL,hash_actual TEXT NOT NULL,paginas INTEGER NOT NULL,codigo TEXT,fecha_origen REAL NOT NULL,creacion_origen REAL NOT NULL,importado TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Entrada',UNIQUE(trabajo_id,hash_original));\n        CREATE TABLE IF NOT EXISTS revisiones_tiff(id INTEGER PRIMARY KEY,archivo_id INTEGER NOT NULL REFERENCES archivos_tiff(id),ruta TEXT NOT NULL,fecha TEXT NOT NULL,operacion TEXT NOT NULL,hash TEXT NOT NULL);\n        CREATE TABLE IF NOT EXISTS operaciones_tiff(id INTEGER PRIMARY KEY,fecha TEXT NOT NULL,trabajo_id INTEGER NOT NULL,archivo_id INTEGER,tipo TEXT NOT NULL,estado TEXT NOT NULL,detalle TEXT NOT NULL);\n        "
CODING_2 = "CREATE TABLE IF NOT EXISTS atajos_numericos(catalogo_id INTEGER PRIMARY KEY REFERENCES catalogos(id),combinacion TEXT NOT NULL CHECK(combinacion IN('Ctrl','Ctrl+Shift')),numero INTEGER NOT NULL CHECK(numero BETWEEN 1 AND 999),UNIQUE(combinacion,numero));\n        CREATE TABLE IF NOT EXISTS correcciones_tiff(id INTEGER PRIMARY KEY,archivo_id INTEGER NOT NULL REFERENCES archivos_tiff(id),pagina INTEGER NOT NULL,ubicacion TEXT NOT NULL,problema TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Pendiente',creado TEXT NOT NULL,resuelto TEXT,nuevo_id INTEGER REFERENCES archivos_tiff(id),incidencia_id INTEGER REFERENCES incidencias(id));"
